package com.hssa.common.validator; import com.hssa.common.dto.pagination.PaginationRequest; import com.hssa.common.constants.ApplicationConstants; public class PaginationValidator { public static void validate(PaginationRequest request) { if (request.getPage() < 0) request.setPage(0); if (request.getSize() <= 0 || request.getSize() > ApplicationConstants.MAX_PAGE_SIZE) request.setSize(ApplicationConstants.DEFAULT_PAGE_SIZE); } }
